"""Standalone report of a bank-context functionality check."""
import json
from build_evaluation_report import STYLE


def render(summary, retrieval, analyses):
    data = json.dumps(dict(summary=summary, retrieval=retrieval, analyses=analyses), ensure_ascii=False)
    data = data.replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return '''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Банковская аналитика в разборе новости</title><style>''' + STYLE + '''</style><main>
<header><div class="eyebrow">Проверка интеграции · 22 октября 2026</div><h1>Банковские отчёты<br>в контексте компании</h1><p class="intro">Поиск по фрагментам отчётов Альфа-Банка и реальные разборы новостей агентом. Даты, страницы и цитаты сохранены.</p><div class="stats" id="stats"></div></header>
<div class="alert"><b>Это проверка работы интеграции, а не измеренная точность аналитики.</b><br>Три выбранных примера не являются независимой разметкой. Банковский прогноз добавляет контекст, но не доказывает влияние на компанию.</div>
<section class="grid"><div class="panel"><h2>Как подключён корпус</h2><ul class="checks"><li>JSONL импортирован напрямую, без повторного OCR.</li><li>9 документов и 138 фрагментов хранятся в PostgreSQL.</li><li>Локальная E5 + полнотекстовый поиск; не больше двух фрагментов одного отчёта в выдаче.</li><li>Агент читает новые таблицы analytics_* ролью без прав записи.</li><li>Источник содержит название документа, дату публикации и страницы.</li></ul></div><div class="panel"><h2>Что проверено</h2><ul id="checks"></ul><p class="note">Полные сетки исходных таблиц и данные графиков отсутствуют. Тексты табличных фрагментов доступны; числа могут содержать ошибки OCR. Старые материалы не трактуются как текущая ситуация.</p></div></section>
<section><h2>Что находит поиск</h2><div id="queries"></div></section><section><h2>Разборы с моделями</h2><div id="cases"></div></section><section class="grid"><div class="panel"><h2>Расход и устойчивость</h2><div id="usage"></div></div><div class="panel"><h2>Файлы результатов</h2><p><a href="results.json">Полные результаты, источники и вызовы инструментов</a></p><p><a href="summary.json">Краткие показатели</a></p><p class="note">Предыдущие отчёты сохранены и описывают прогоны без банковского контекста.</p></div></section></main>
<script type="application/json" id="data">''' + data + '''</script><script>
const D=JSON.parse(document.getElementById('data').textContent),S=D.summary,R=D.retrieval;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const used=S.cases.reduce((n,c)=>n+(c.cited_bank_sources||0),0);
document.getElementById('stats').innerHTML=[['Банковских отчётов',R.counts.documents],['Фрагментов / векторов',`${R.counts.chunks} / ${R.counts.vectors}`],['Завершено разборов',`${S.completed} / ${S.planned}`],['Банковских источников в цитатах',used],['Расход по usage.cost',`$${S.reported_cost_usd.toFixed(2)}`]].map(([n,v])=>`<div class="stat"><strong>${v}</strong><span>${n}</span></div>`).join('');
document.getElementById('checks').innerHTML=[`Все ${R.counts.chunks} фрагментов имеют эмбеддинги.`,`Максимальный вход E5: ${R.max_input_tokens} из ${R.token_limit} токенов; обрезания нет.`,`Будущие документы отфильтрованы; до 2021 года выдача пуста.`,`Роль ${R.permissions.role}: SELECT разрешён, INSERT и UPDATE запрещены.`].map(x=>`<li>${esc(x)}</li>`).join('');
document.getElementById('queries').innerHTML=R.queries.map(q=>`<details class="panel case"><summary>${esc(q.query)}</summary>`+q.sources.map(s=>`<div class="claim"><h3>${esc(s.title)}</h3><p class="note">${esc(s.published_at)} · ${esc(s.locator)}</p><blockquote style="white-space:pre-wrap">${esc(s.text)}</blockquote></div>`).join('')+'</details>').join('');
document.getElementById('cases').innerHTML=D.analyses.map(row=>{if(!row.result)return `<div class="panel">${esc(row.company_id)}: ${esc(row.error)}</div>`;const x=row.result,ins=x.result,m=S.cases.find(c=>c.company_id===row.company_id&&c.news_id===row.news_id),sources=Object.fromEntries(x.retrieved_sources.map(s=>[s.source_id,s]));return `<details class="panel case"><summary>${esc(row.company_id)} · ${esc(x.event.title)}</summary><p>${esc(ins.summary)}</p><p class="note">Статус ${esc(ins.status)}. Банковских фрагментов в контексте: ${m.bank_sources}; использовано в цитатах: ${m.cited_bank_sources}. Подготовка новости переиспользована; исследование и анализ выполнены заново.</p>`+ins.claims.map(c=>`<div class="claim"><span class="pill">${c.kind==='fact'?'Факт источника':'Гипотеза'}</span>${esc(c.text)}<details><summary>Цитаты${c.evidence.some(e=>e.source_id.startsWith('bank:'))?' · есть банковский источник':''}</summary>`+c.evidence.map(e=>`<blockquote><b>${esc(sources[e.source_id]?.title||e.source_id)}</b><p class="note">${esc(sources[e.source_id]?.locator||e.source_id)}</p>${esc(e.quote)}</blockquote>`).join('')+'</details></div>').join('')+'<h3>Ограничения</h3><ul>'+ins.missing_data.map(t=>`<li>${esc(t)}</li>`).join('')+'</ul><details><summary>Вызовы инструментов</summary><pre style="white-space:pre-wrap">'+esc(JSON.stringify(x.trace,null,2))+'</pre></details></details>'}).join('');
document.getElementById('usage').innerHTML=`<p>${S.model_attempts} попыток вызова моделей; $${S.reported_cost_usd.toFixed(4)} по usage шлюза. Стоимость ответов без usage неизвестна. Классификация и извлечение события переиспользованы из предыдущего прогона.</p><pre style="white-space:pre-wrap">${esc(JSON.stringify(S.statuses,null,2))}</pre>`;
document.querySelectorAll('#cases > .case').forEach((el,i)=>{const row=D.analyses.filter(r=>r.result)[i],b=row?.result.brief;if(!b)return;const levels={high:'Высокая',medium:'Средняя',low:'Низкая'};el.querySelector('summary').insertAdjacentHTML('afterend',`<div class="panel"><h3>Короткая карточка</h3><p><b>О новости:</b> ${esc(b.news_summary)}</p><p><b>Для компании:</b> ${esc(b.short_answer)}</p><p><span class="pill">${esc(levels[b.classification.importance]||'Важность не оценена')}</span> ${esc(b.classification.topics.join(' · '))}</p><p class="note">${esc(b.classification.importance_reason)} Метод: ${esc(b.classification.importance_method||'недоступен')}. Статус: ${esc(b.status)}.</p></div>`)});
document.getElementById('usage').insertAdjacentHTML('beforeend',`<p>Короткие поля и оценка важности готовы: ${S.brief_completed} / ${S.planned}. <a href="compact-results.json">Компактные результаты JSON</a>.</p>`);
if(S.default_cli){const c=S.default_cli;document.getElementById('usage').insertAdjacentHTML('beforeend',`<h3>Обычный Docker-запуск</h3><p>Полный пайплайн для ${esc(c.company_id)}: анализ ${esc(c.status)}, короткая карточка ${esc(c.brief_status)}, банковских источников ${c.bank_sources}. ${c.model_attempts} попыток, $${c.reported_cost_usd.toFixed(2)} по usage; этот расход указан отдельно от трёх проверочных разборов.</p><p><a href="default-cli-brief.json">Готовый brief.json для интерфейса</a> · <a href="default-cli-result.json">Полный результат</a></p>`);}
</script></html>'''
